def parser(log: str) -> dict[str, str]:
    import json

    results: dict[str, str] = {}

    pass_events = {"ok", "pass", "passed", "success", "succeeded"}
    skip_events = {"skip", "skipped", "ignore", "ignored"}
    fail_events = {
        "fail", "failed",
        "error", "errored",
        "timeout", "timed_out",
        "cancelled", "canceled",
        "aborted", "terminated",
    }

    for line in log.splitlines():
        line = line.strip().lstrip("\ufeff")
        if not line:
            continue

        try:
            record = json.loads(line)
        except (json.JSONDecodeError, TypeError):
            continue

        if not isinstance(record, dict):
            continue

        record_type = record.get("type")
        if not isinstance(record_type, str) or record_type.lower() != "test":
            continue

        name = record.get("name")
        event = record.get("event")
        if not isinstance(name, str) or not name.strip():
            continue
        if not isinstance(event, str):
            continue

        event = event.strip().lower().replace("-", "_").replace(" ", "_")

        if event in {"started", "start"}:
            # If the log ends before a terminal event, the test did not
            # complete successfully and must not disappear from the results.
            results[name] = "fail"
        elif event in pass_events:
            results[name] = "pass"
        elif event in skip_events:
            results[name] = "skip"
        elif event in fail_events:
            results[name] = "fail"

    return results
